module potato_optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [3:0] L,\n    input [7:0] a [0:7],\n    input [19:0] c [0:7],\n    output reg [31:0] result,\n    output reg done\n);\n\n    // States\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] CALCULATE = 2'd2;\n    localparam [1:0] DONE = 2'd3;\n\n    reg [1:0] state;\n    reg [7:0] total_potatoes;\n    reg [19:0] total_cost;\n    reg [3:0] current_bag;\n    reg [3:0] check_k;\n    reg [7:0] check_t;\n    reg [31:0] best_product;\n    reg [19:0] dp_cost [0:8][0:500];\n    reg dp_valid [0:8][0:500];\n    integer i, j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            total_potatoes <= 8'd0;\n            total_cost <= 20'd0;\n            current_bag <= 4'd0;\n            check_k <= 4'd0;\n            check_t <= 8'd0;\n            best_product <= 32'd0;\n            for (i = 0; i <= 8; i = i + 1) begin\n                for (j = 0; j <= 500; j = j + 1) begin\n                    dp_cost[i][j] <= 20'd0;\n                    dp_valid[i][j] <= 1'b0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        total_potatoes <= 8'd0;\n                        total_cost <= 20'd0;\n                        for (i = 0; i < N; i = i + 1) begin\n                            total_potatoes <= total_potatoes + a[i];\n                            total_cost <= total_cost + c[i];\n                        end\n                        for (i = 0; i <= 8; i = i + 1) begin\n                            for (j = 0; j <= 500; j = j + 1) begin\n                                dp_valid[i][j] <= 1'b0;\n                            end\n                        end\n                        dp_cost[0][0] <= 20'd0;\n                        dp_valid[0][0] <= 1'b1;\n                        current_bag <= 4'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                COMPUTE: begin\n                    if (current_bag < N) begin\n                        for (i = 8; i >= 1; i = i - 1) begin\n                            for (j = 500; j >= a[current_bag]; j = j - 1) begin\n                                if (dp_valid[i-1][j - a[current_bag]]) begin\n                                    if (!dp_valid[i][j] || (dp_cost[i-1][j - a[current_bag]] + c[current_bag] < dp_cost[i][j])) begin\n                                        dp_cost[i][j] <= dp_cost[i-1][j - a[current_bag]] + c[current_bag];\n                                        dp_valid[i][j] <= 1'b1;\n                                    end\n                                end\n                            end\n                        end\n                        current_bag <= current_bag + 4'd1;\n                    end else begin\n                        check_k <= 4'd0;\n                        check_t <= 8'd0;\n                        best_product <= 32'd0;\n                        state <= CALCULATE;\n                    end\n                end\n                CALCULATE: begin\n                    if (check_k <= N) begin\n                        if (check_k == L) begin\n                            for (j = 0; j <= 500; j = j + 1) begin\n                                if (dp_valid[check_k][j] && dp_valid[N - check_k][total_potatoes - j]) begin\n                                    if (j > 0 && (total_potatoes - j) > 0) begin\n                                        reg [39:0] numerator;\n                                        reg [39:0] denominator;\n                                        reg [31:0] product;\n                                        numerator = dp_cost[check_k][j] * (total_cost - dp_cost[check_k][j]);\n                                        numerator = numerator << 16;\n                                        denominator = j * (total_potatoes - j);\n                                        if (denominator != 0) begin\n                                            product = numerator / denominator;\n                                            if (product < best_product) begin\n                                                best_product <= product;\n                                            end\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                        if (check_k == N - L && L != N - L) begin\n                            for (j = 0; j <= 500; j = j + 1) begin\n                                if (dp_valid[check_k][j] && dp_valid[N - check_k][total_potatoes - j]) begin\n                                    if (j > 0 && (total_potatoes - j) > 0) begin\n                                        reg [39:0] numerator;\n                                        reg [39:0] denominator;\n                                        reg [31:0] product;\n                                        numerator = dp_cost[check_k][j] * (total_cost - dp_cost[check_k][j]);\n                                        numerator = numerator << 16;\n                                        denominator = j * (total_potatoes - j);\n                                        if (denominator != 0) begin\n                                            product = numerator / denominator;\n                                            if (product < best_product) begin\n                                                best_product <= product;\n                                            end\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                        check_k <= check_k + 4'd1;\n                    end else begin\n                        result <= best_product;\n                        done <= 1'b1;\n                        state <= DONE;\n                    end\n                end\n                DONE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule